define({"topics":[{"title":"Removing the magnet service access trim","shortdesc":"<p class=\"shortdesc\">Removes the service access trim. The trim panel covers the screws securing the front and rear service access panels.<\/p>","href":"t_RemovingTheServiceAccessTrim_8.html","attributes":{"data-id":"id_2002821"},"menu":{"hasChildren":false},"tocID":"id_2002821-d46e57536","topics":[]},{"title":"Removing the magnet front service access panel","shortdesc":"<p class=\"shortdesc\">Removes the front service access panel from the magnet to allow access to components mounted on the left-hand side of the magnet.<\/p>","href":"t_RemovingTheFrontServiceAccessPanel_7.html","attributes":{"data-id":"id_2002823"},"menu":{"hasChildren":false},"tocID":"id_2002823-d46e57638","topics":[]},{"title":"Removing the magnet rear service access panel","shortdesc":"<p class=\"shortdesc\">Removes the rear service access panel from the magnet to allow access to components mounted on the left-hand side of the magnet.<\/p>","href":"t_RemovingTheRearServiceAccessPanel_5.html","attributes":{"data-id":"id_2002966"},"menu":{"hasChildren":false},"tocID":"id_2002966-d46e57740","topics":[]},{"title":"Removing the right hand lower access panel","shortdesc":"<p class=\"shortdesc\">Removes the right-hand lower access panel from the magnet front cover.<\/p>","href":"t_RemovingTheRightHandLowerAccessPanel_4.html","attributes":{"data-id":"id_2008054"},"menu":{"hasChildren":false},"tocID":"id_2008054-d46e57842","topics":[]},{"title":"Removing the table interface cover","shortdesc":"<p class=\"shortdesc\">Removes the fixed or dockable table interface cover from the magnet front cover.<\/p>","href":"t_RemovingTheFixedTableInterfaceCover_4.html","attributes":{"data-id":"id_2002927"},"menu":{"hasChildren":false},"tocID":"id_2002927-d46e57944","topics":[]},{"title":"Removing the magnet left-hand lower front cover","shortdesc":"<p class=\"shortdesc\">Removes the lower cover from the left-hand front corner of the magnet.<\/p>","href":"t_RemovingTheLeftHandLowerFrontCover_2.html","attributes":{"data-id":"id_2002997"},"menu":{"hasChildren":false},"tocID":"id_2002997-d46e58046","topics":[]},{"title":"Removing the magnet upper service access panel","shortdesc":"<p class=\"shortdesc\">Removes the upper service access panel allowing access to components mounted on top of the magnet.<\/p>","href":"t_RemovingTheUpperServiceAccessPanel_3.html","attributes":{"data-id":"id_2002968"},"menu":{"hasChildren":false},"tocID":"id_2002968-d46e58148","topics":[]},{"title":"Removing the magnet rear trim ring","shortdesc":"<p class=\"shortdesc\">Removes the rear trim ring from the rear endbell.  The trim ring covers the bolts securing the magnet rear enclosures.<\/p>","href":"t_RemovingTheRearTrimRing_4.html","attributes":{"data-id":"id_2002972"},"menu":{"hasChildren":false},"tocID":"id_2002972-d46e58250","topics":[]},{"title":"Removing the magnet rear cable cover","shortdesc":"<p class=\"shortdesc\">Removes the rear cable cover from the magnet enclosure.<\/p>","href":"t_RemovingTheRearCableCover_3.html","attributes":{"data-id":"id_2002978"},"menu":{"hasChildren":false},"tocID":"id_2002978-d46e58352","topics":[]},{"title":"Removing the magnet right-hand top cover","shortdesc":"<p class=\"shortdesc\">Removes the cover from the top of the right-hand side of the magnet enclosure.<\/p>","href":"t_RemovingTheRightHandTopCover_2.html","attributes":{"data-id":"id_2002984"},"menu":{"hasChildren":false},"tocID":"id_2002984-d46e58454","topics":[]},{"title":"Removing the magnet left-hand upper front cover","shortdesc":"<p class=\"shortdesc\">Removes the upper cover from the front left-hand corner of the magnet.<\/p>","href":"t_RemovingTheLeftHandUpperFrontCover.html","attributes":{"data-id":"id_2002995"},"menu":{"hasChildren":false},"tocID":"id_2002995-d46e58557","topics":[]}]});